mapper.select:


    inner join sys_user u on u.user_name = dinspectionplanday.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    dinspectionplanday.del_flag = '0' and dinspectionplanday.status !=4
     and dinspectionplanday.plan_id = #{planId}
     and dinspectionplanday.day = #{day}
     and dinspectionplanday.day >= #{dayBegin} and #{dayEnd}>= dinspectionplanday.day
     and dinspectionplanday.inspection_start_time = #{inspectionStartTime}
     and dinspectionplanday.inspection_end_time = #{inspectionEndTime}


     and dinspectionplanday.reason = #{reason}
     and dinspectionplanday.status = #{status}
     and dinspectionplanday.sign_type = #{signType}
     and dinspectionplanday.inspector_name = #{inspectorName}
     and dinspectionplanday.inspector_true_name = #{inspectorTrueName}


${params.dataScope}
